fn binary_search(a: &[i32], key: i32) -> usize {
    let mut lo = 0;
    let mut hi = a.len();
    while lo < hi {
        // Prevent potential overflow in index calculation
        let mid = lo + (hi - lo) / 2;
        if a[mid] < key {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo
}

